<script setup>
import {ref,reactive,computed,onMounted} from 'vue';import {Download,ArrowDownLeft,ArrowUpRight,Wallet} from 'lucide-vue-next';import {api} from '../lib/api';import {currency,dateText,today} from '../lib/format';import StatePanel from '../components/StatePanel.vue';
const dates=reactive({from:today().slice(0,7)+'-01',to:today()}),rows=ref([]),loading=ref(true),error=ref(''),range=reactive({from:'',to:''});const totals=computed(()=>rows.value.reduce((a,r)=>({received:a.received+Number(r.received_amount),refunded:a.refunded+Number(r.refunded_amount),net:a.net+Number(r.net_cash_flow)}),{received:0,refunded:0,net:0}));const max=computed(()=>Math.max(1,...rows.value.map(r=>Math.max(Number(r.received_amount),Number(r.refunded_amount)))));
async function load(){loading.value=true;error.value='';try{if(dates.from>dates.to)throw Error('วันสิ้นสุดต้องไม่ก่อนวันเริ่ม');rows.value=(await api('/admin/reports/cash-flow?'+new URLSearchParams(dates))).data;Object.assign(range,dates);}catch(e){error.value=e.message;}finally{loading.value=false;}}
function exportCsv(){const lines=[['วันที่','รับเงิน','คืนเงิน','กระแสเงินสดสุทธิ'],...rows.value.map(r=>[String(r.event_date).slice(0,10),r.received_amount,r.refunded_amount,r.net_cash_flow])];const blob=new Blob(['\uFEFF'+lines.map(r=>r.join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=`cash-flow-${range.from}-${range.to}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
onMounted(load);
</script>
<template><section class="admin-page"><div class="page-heading"><div><p class="eyebrow">FINANCIAL OVERVIEW</p><h1>รายงานกระแสเงินสด</h1><p class="muted">ยอดรับและคืนเงินตามวันที่เกิดรายการ</p></div><button class="btn outline" :disabled="loading||!!error||!rows.length" @click="exportCsv"><Download :size="17"/> ดาวน์โหลด CSV</button></div><form class="panel filter-bar" @submit.prevent="load"><label>ตั้งแต่วันที่<input type="date" v-model="dates.from" required/></label><label>ถึงวันที่<input type="date" v-model="dates.to" :min="dates.from" required/></label><button class="btn primary" :disabled="loading">ดูรายงาน</button></form><StatePanel :loading="loading" :error="error" @retry="load"/><template v-if="!loading&&!error"><div class="stats-grid three"><article class="stat-card"><span class="stat-icon"><ArrowDownLeft/></span><p>ยอดรับเงิน</p><strong>{{ currency(totals.received) }}</strong></article><article class="stat-card"><span class="stat-icon orange"><ArrowUpRight/></span><p>ยอดคืนเงิน</p><strong>{{ currency(totals.refunded) }}</strong></article><article class="stat-card"><span class="stat-icon blue"><Wallet/></span><p>กระแสเงินสดสุทธิ</p><strong>{{ currency(totals.net) }}</strong></article></div><div class="panel"><div class="section-heading"><div><h2>รายการรายวัน</h2><p class="muted">{{ dateText(range.from) }} – {{ dateText(range.to) }}</p></div><div class="chart-legend"><span class="dot teal"/> รับเงิน <span class="dot orange"/> คืนเงิน</div></div><StatePanel :empty="!rows.length"/><div v-if="rows.length" class="cash-chart"><div class="chart-row" v-for="r in rows" :key="r.event_date"><span>{{ dateText(r.event_date) }}</span><div class="chart-bars"><div class="chart-bar teal" :style="{width:Number(r.received_amount)/max*100+'%'}" :aria-label="'รับเงิน '+currency(r.received_amount)"/><div class="chart-bar orange" :style="{width:Number(r.refunded_amount)/max*100+'%'}" :aria-label="'คืนเงิน '+currency(r.refunded_amount)"/></div><strong>{{ currency(r.net_cash_flow) }}</strong></div></div><div v-if="rows.length" class="table-wrap"><table><thead><tr><th>วันที่</th><th>รับเงิน</th><th>คืนเงิน</th><th>สุทธิ</th></tr></thead><tbody><tr v-for="r in rows" :key="r.event_date"><td>{{ dateText(r.event_date) }}</td><td>{{ currency(r.received_amount) }}</td><td>{{ currency(r.refunded_amount) }}</td><td><strong>{{ currency(r.net_cash_flow) }}</strong></td></tr></tbody></table></div></div><p class="field-help">รายงานนี้แสดงเงินรับจริงที่ตรวจสำเร็จและรายการคืนเงินที่บันทึกแล้ว ไม่รวมรายการรอตรวจ และไม่ใช่รายงานกำไร</p></template></section></template>
